// rd_kafka_version() has no inputs and returns an int version. We just call it to exercise the path.
int ver = rd_kafka_version();
// Basic sanity: version should be non-zero for a built library; if zero, bail to steer fuzzer.
if (ver == 0) { FUZZ_BAIL(); }
// Validation: No resources to manage; simple call coverage.

// Returns a library-owned const char*. Must not be freed or modified.
const char *vstr = rd_kafka_version_str();
// Touch the string (read-only) if non-NULL.
if (vstr && *vstr) { /* no-op read */ }
// Validation: pointer is library-owned; we don't store or free it.

// Returns a library-owned const char* of comma-separated debug contexts.
const char *ctx = rd_kafka_get_debug_contexts();
if (ctx && *ctx) { /* no-op read */ }
// Validation: read-only use only; no ownership to manage.

// Prepare out-parameters; must be non-NULL.
const rd_kafka_err_desc *errdescs = NULL;
size_t cnt = 0;
rd_kafka_get_err_descs(&errdescs, &cnt);
// The returned array pointer is library-owned; do not free or modify.
if (!errdescs || cnt == 0) { /* Allowed, but bail to guide fuzzer deeper into populated paths */ FUZZ_BAIL(); }
// Validation: out-params provided, we don't retain or free the returned memory.

// Generate a random error code and translate to string.
rd_kafka_resp_err_t err = *FUZZ_PARAM(rd_kafka_resp_err_t);
const char *s = rd_kafka_err2str(err);
if (s && *s) { /* read-only use */ }
// Validation: returned pointer is library-owned; no freeing.

// Generate a random error code and translate to enum name string.
rd_kafka_resp_err_t err = *FUZZ_PARAM(rd_kafka_resp_err_t);
const char *s = rd_kafka_err2name(err);
if (s && *s) { /* read-only use */ }
// Validation: returned pointer is library-owned; no freeing.

// Obtain last error on this thread (legacy API context). Safe to call unconditionally for coverage.
rd_kafka_resp_err_t last = rd_kafka_last_error();
(void)last;
// Validation: No resources involved.

// Convert a random errno value to rd_kafka_resp_err_t (deprecated API).
int e = (int)(*FUZZ_PARAM(unsigned int) % 256); // constrain into a plausible errno range
rd_kafka_resp_err_t mapped = rd_kafka_errno2err(e);
(void)mapped;
// Validation: Pure value conversion; no resources.

// Get thread-local errno used by librdkafka (deprecated API).
int e = rd_kafka_errno();
(void)e;
// Validation: No resource management needed.

// Prepare an output buffer for fatal error description (written only if a fatal error is present).
size_t cap = (size_t)((*FUZZ_PARAM(unsigned int) % 256) + 16); // [16..271]
std::string buf(cap, '\0');
rd_kafka_resp_err_t code = rd_kafka_fatal_error(rk, buf.data(), buf.size());
// If fatal error present, the buffer may now contain a NUL-terminated string; we can touch it safely.
if (code != 0 && !buf.empty()) { volatile char c = buf[0]; (void)c; }
// Output rk back since ownership is unchanged and it remains valid.
// Validation: rk is a valid client handle (provided by runtime). Buffer is writable and sized.

// Trigger a fabricated fatal error for testing.
rd_kafka_resp_err_t err = *FUZZ_PARAM(rd_kafka_resp_err_t);
std::string reason = FUZZ_PARAM_STR();
if (reason.empty()) { FUZZ_BAIL(); }
rd_kafka_resp_err_t r = rd_kafka_test_fatal_error(rk, err, reason.c_str());
(void)r;
// Validation: rk remains valid; reason is a valid C-string.

// Extract the error code from the error object (NULL allowed per API, but fuzzer provides non-NULL inputs).
rd_kafka_resp_err_t code = rd_kafka_error_code(error);
(void)code;
// Keep the error object alive by returning it as output.
// Validation: No ownership changes; read-only query.

// Get the error name string. Lifetime tied to the error object; do not free.
const char *name = rd_kafka_error_name(error);
if (name && *name) { /* read-only touch */ }
// Return the error unchanged.
// Validation: Pointer lifetime tied to 'error'; we don't destroy it here.

// Get the detailed error string. Lifetime tied to the error object; do not free.
const char *s = rd_kafka_error_string(error);
if (s && *s) { /* read-only touch */ }
// Return the error unchanged to keep it in the pool.
// Validation: Proper lifetime honored.

// Check if the error is fatal.
int is_fatal = rd_kafka_error_is_fatal(error);
(void)is_fatal;
// Keep the error object alive.
// Validation: Read-only query; no ownership change.

// Check if the error is retriable.
int retriable = rd_kafka_error_is_retriable(error);
(void)retriable;
// Keep the error object in the pool.
// Validation: Read-only; no ownership change.

// Query if the transactional error requires abort.
int req_abort = rd_kafka_error_txn_requires_abort(error);
(void)req_abort;
// Return error unchanged.
// Validation: Read-only query; ownership unchanged.

// Destroy/free an error object. After this call, 'error' must not be used.
rd_kafka_error_destroy(error);
// Do not return 'error' to the pool to avoid use-after-free.
// Validation: Ownership transferred to library for destruction; object dropped.

// Create a new error object with a formatted message. Caller must later destroy it.
rd_kafka_resp_err_t code = *FUZZ_PARAM(rd_kafka_resp_err_t);
std::string msg = FUZZ_PARAM_STR();
// Use a simple printf-style format to exercise variadic handling.
rd_kafka_error_t *error = rd_kafka_error_new(code, "%s", msg.c_str());
if (!error) { FUZZ_BAIL(); }
// Optionally track the code on the object for downstream assertions.
FUZZ_SET_ATTR_INT(error, "code", (int)code);
// Output the newly created error to return ownership to the fuzzer pool.
// Validation: Successfully allocates an error object; lifetime managed by pool until destroyed by another stub.

// This API must only be used for standalone rd_kafka_topic_partition_t, not list-owned elements.
// Enforce with an attribute set by creators (e.g., rd_kafka_event_topic_partition()).
int standalone = FUZZ_GET_ATTR_INT(rktpar, "standalone");
if (!standalone) { // Unknown provenance or list-owned; do not destroy
    FUZZ_BAIL();
}
rd_kafka_topic_partition_destroy(rktpar);
// Do not return rktpar; it is destroyed.
// Validation: Prevents destroying list-owned elements via attribute gating; avoids double-free.

// Enforce lifetime: if rktpar is list-owned, ensure the parent matches.
void *parent_attr = FUZZ_GET_ATTR_PTR(rktpar, "parent_list");
if (parent_attr && parent_attr != (void*)parent_list) { FUZZ_BAIL(); }
// Choose a leader epoch: either -1 (clear) or a non-negative epoch.
int choose_clear = (int)(*FUZZ_PARAM(unsigned int) % 4 == 0);
int32_t leader_epoch = choose_clear ? -1 : (int32_t)(*FUZZ_PARAM(unsigned int) % 100000);
rd_kafka_topic_partition_set_leader_epoch(rktpar, leader_epoch);
// Track the last-set epoch for potential downstream validation.
FUZZ_SET_ATTR_INT(rktpar, "leader_epoch", (int)leader_epoch);
// Validation: rktpar kept alive by also returning parent_list; inputs unchanged and returned to pool.

// Enforce lifetime: if rktpar is list-owned, require the parent to be supplied and matching.
void *parent_attr = FUZZ_GET_ATTR_PTR(rktpar, "parent_list");
if (parent_attr && parent_attr != (void*)parent_list) { FUZZ_BAIL(); }
int32_t le = rd_kafka_topic_partition_get_leader_epoch(rktpar);
(void)le;
// Validation: Read-only query; rktpar and parent_list are returned to maintain lifetime.

// Create a new list with a small initial allocation.
int size = (int)(*FUZZ_PARAM(unsigned int) % 17); // 0..16
rd_kafka_topic_partition_list_t *rktparlist = rd_kafka_topic_partition_list_new(size);
if (!rktparlist) { FUZZ_BAIL(); }
// Mark that no child pointers have been exported yet.
FUZZ_SET_ATTR_INT(rktparlist, "child_exported", 0);
// Validation: Caller must later destroy with rd_kafka_topic_partition_list_destroy(); object returned to pool.

// Prevent destroying a list if we've exported child element pointers to the pool.
int child_exported = FUZZ_GET_ATTR_INT(rkparlist, "child_exported");
if (child_exported) { FUZZ_BAIL(); }
rd_kafka_topic_partition_list_destroy(rkparlist);
// Validation: List destroyed and not returned; avoids dangling child pointers by attribute gating.

// Add a single topic+partition element.
std::string topic = FUZZ_PARAM_STR();
if (topic.empty()) { FUZZ_BAIL(); }
int32_t partition = (int32_t)(*FUZZ_PARAM(unsigned int) % 1024);
rd_kafka_topic_partition_t *rktpar = rd_kafka_topic_partition_list_add(rktparlist, topic.c_str(), partition);
if (!rktpar) { FUZZ_BAIL(); }
// Track ownership: element is list-owned; not standalone.
FUZZ_SET_ATTR_INT(rktpar, "standalone", 0);
FUZZ_SET_ATTR_PTR(rktpar, "parent_list", (void*)rktparlist);
FUZZ_SET_ATTR_INT(rktparlist, "child_exported", 1);
// Initialize leader_epoch tracking metadata to unknown (-1).
FUZZ_SET_ATTR_INT(rktpar, "leader_epoch", -1);
// Validation: Returns both the list (owner) and the new element; element must only be used while list is alive.

// Add a range of partitions [start..stop] for a topic.
std::string topic = FUZZ_PARAM_STR();
if (topic.empty()) { FUZZ_BAIL(); }
int32_t base = (int32_t)(*FUZZ_PARAM(unsigned int) % 1000);
int32_t span = (int32_t)(*FUZZ_PARAM(unsigned int) % 8); // keep small
int32_t start = base;
int32_t stop  = base + span;
rd_kafka_topic_partition_list_add_range(rktparlist, topic.c_str(), start, stop);
// Validation: Mutates list by adding elements; no element pointers exported here.

// Prefer removing an existing element, otherwise attempt a random key.
const rd_kafka_topic_partition_list_t *pl = rktparlist;
int32_t partition = (int32_t)(*FUZZ_PARAM(unsigned int) % 1024);
const char *topic = NULL;
if (pl->cnt > 0) {
    topic = pl->elems[0].topic;
    partition = pl->elems[0].partition;
} else {
    static std::string t = FUZZ_PARAM_STR();
    if (t.empty()) { FUZZ_BAIL(); }
    topic = t.c_str();
}
(void)rd_kafka_topic_partition_list_del(rktparlist, topic, partition);
// Validation: Safe regardless of found/not found; list remains valid and is returned.

// Delete by index; enforce in-bounds index when list non-empty.
if (rktparlist->cnt <= 0) { FUZZ_BAIL(); }
int idx = (int)(*FUZZ_PARAM(unsigned int) % (unsigned)rktparlist->cnt);
(void)rd_kafka_topic_partition_list_del_by_idx(rktparlist, idx);
// Validation: Ensures idx within bounds as required; list returned to pool.

// Create a deep copy of the list.
rd_kafka_topic_partition_list_t *dst = rd_kafka_topic_partition_list_copy(src);
if (!dst) { FUZZ_BAIL(); }
// No child pointers are exported here.
FUZZ_SET_ATTR_INT(dst, "child_exported", 0);
// Validation: Copy must be destroyed later by destroy() stub; both lists returned to pool.

// Set offset for an element. Prefer a present element for success; otherwise arbitrary values are fine.
const char *topic = NULL; int32_t partition = 0;
if (rktparlist->cnt > 0) {
    topic = rktparlist->elems[0].topic;
    partition = rktparlist->elems[0].partition;
} else {
    static std::string t = FUZZ_PARAM_STR();
    if (t.empty()) { FUZZ_BAIL(); }
    topic = t.c_str();
    partition = (int32_t)(*FUZZ_PARAM(unsigned int) % 1024);
}
// Offset may be a logical negative or absolute; use a full range.
int64_t offset = (int64_t)(*(const long long*)FUZZ_PARAM(long long));
(void)rd_kafka_topic_partition_list_set_offset(rktparlist, topic, partition, offset);
// Validation: API handles not-found by returning UNKNOWN_PARTITION; list returned.

// To guarantee a non-NULL return (so rktpar output is valid), require at least one element.
if (rktparlist->cnt <= 0) { FUZZ_BAIL(); }
const char *topic = rktparlist->elems[0].topic;
int32_t partition = rktparlist->elems[0].partition;
rd_kafka_topic_partition_t *rktpar = rd_kafka_topic_partition_list_find(rktparlist, topic, partition);
if (!rktpar) { FUZZ_BAIL(); }
// Track parent linkage for lifetime validation in other stubs.
FUZZ_SET_ATTR_INT(rktpar, "standalone", 0);
FUZZ_SET_ATTR_PTR(rktpar, "parent_list", (void*)rktparlist);
FUZZ_SET_ATTR_INT(rktparlist, "child_exported", 1);
// Validation: Returns both list and found element; element remains list-owned.

// Use default comparator by passing NULL, which sorts by (topic, partition).
rd_kafka_topic_partition_list_sort(rktparlist, NULL, NULL);
// Validation: Mutates list order only; list returned.

// Create headers with a small initial capacity.
size_t initial = (size_t)(*FUZZ_PARAM(unsigned int) % 9); // 0..8
rd_kafka_headers_t *hdrs = rd_kafka_headers_new(initial);
if (!hdrs) { FUZZ_BAIL(); }
// Mark as writable/user-owned in our metadata.
FUZZ_SET_ATTR_INT(hdrs, "read_only", 0);
// Validation: Caller must destroy with rd_kafka_headers_destroy(); object returned to pool.

// Destroy the headers list. Any previously returned pointers from this list become invalid.
rd_kafka_headers_destroy(hdrs);
// Validation: Do not return hdrs; ensure no further use after destruction.

// Deep-copy the headers list.
rd_kafka_headers_t *dst = rd_kafka_headers_copy(src);
if (!dst) { FUZZ_BAIL(); }
FUZZ_SET_ATTR_INT(dst, "read_only", 0);
// Validation: dst must later be destroyed; both src and dst returned to pool.

// Add a header (name,value). Name/value are copied by the library.
std::string name = FUZZ_PARAM_STR();
if (name.empty()) { FUZZ_BAIL(); }
std::string val = FUZZ_PARAM_STR();
// Randomly decide to use -1 (C-string) semantics or explicit sizes.
int use_cstr_name = (int)(*FUZZ_PARAM(unsigned int) & 1);
int use_cstr_val  = (int)(*FUZZ_PARAM(unsigned int) & 1);
ssize_t name_size = use_cstr_name ? (ssize_t)-1 : (ssize_t)std::min<size_t>(val.size() > 0 ? name.size() : name.size(), name.size());
const void *value_ptr = (const void*)val.data();
ssize_t value_size = use_cstr_val ? (ssize_t)-1 : (ssize_t)val.size();
(void)rd_kafka_header_add(hdrs, name.c_str(), name_size, value_ptr, value_size);
// Validation: hdrs mutated on success; remains user-owned and is returned.

// Remove all headers matching a key.
std::string name = FUZZ_PARAM_STR();
if (name.empty()) { FUZZ_BAIL(); }
(void)rd_kafka_header_remove(hdrs, name.c_str());
// Validation: hdrs remains valid; removal may or may not find matches.

// Retrieve the last header with a given name; provide non-NULL out-params.
std::string name = FUZZ_PARAM_STR();
if (name.empty()) { FUZZ_BAIL(); }
const void *valuep = NULL; size_t sizep = 0;
rd_kafka_resp_err_t r = rd_kafka_header_get_last(hdrs, name.c_str(), &valuep, &sizep);
if (!r) {
    // On success, valuep may be NULL (explicit NULL header), but sizep is valid.
    if (sizep > 0 && valuep) { volatile unsigned char c = ((const unsigned char*)valuep)[0]; (void)c; }
}
// Validation: Pointers only used if call succeeded; hdrs lifetime maintained.

// Iterate by index for a given key; start at a random small idx.
std::string name = FUZZ_PARAM_STR();
if (name.empty()) { FUZZ_BAIL(); }
